use crate::{cards::{Card, Rank, Shoe}, modes::Mode};

#[derive(Clone, Debug)]
pub struct Hand { pub cards: Vec<Card>, pub bet: u64, pub surrendered: bool, pub doubled: bool }
impl Hand { pub fn new(bet: u64) -> Self { Self { cards: Vec::new(), bet, surrendered: false, doubled: false } } pub fn value(&self) -> (u8, bool) { let mut total = 0; let mut aces = 0; for card in &self.cards { total += card.rank.value(); if card.rank == Rank::Ace { aces += 1; } } while total > 21 && aces > 0 { total -= 10; aces -= 1; } (total, aces > 0) } pub fn blackjack(&self) -> bool { self.cards.len() == 2 && self.value().0 == 21 } pub fn pair(&self) -> bool { self.cards.len() == 2 && self.cards[0].rank == self.cards[1].rank } }

pub fn payout(player: &Hand, dealer: &Hand, mode: Mode) -> i64 { if player.surrendered { return -(player.bet as i64 / 2); } let (p, _) = player.value(); let (d, _) = dealer.value(); if p > 21 { return -(player.bet as i64); } if dealer.blackjack() && !player.blackjack() { return -(player.bet as i64); } if player.blackjack() && !dealer.blackjack() { return (player.bet * mode.config().multiplier * mode.config().blackjack_num / mode.config().blackjack_den) as i64; } if d > 21 || p > d { player.bet as i64 } else if p == d { player.bet as i64 } else { -(player.bet as i64) } }

#[derive(Clone, Debug)]
pub struct Round { pub shoe: Shoe, pub dealer: Hand, pub hands: Vec<Hand>, pub active: usize, pub over: bool, pub settled: bool, pub result: i64, pub insurance: u64 }
impl Round { pub fn new(mut shoe: Shoe, bet: u64) -> Self { let mut player = Hand::new(bet); let mut dealer = Hand::new(0); player.cards.push(shoe.deal()); dealer.cards.push(shoe.deal()); player.cards.push(shoe.deal()); dealer.cards.push(shoe.deal()); Self { shoe, dealer, hands: vec![player], active: 0, over: false, settled: false, result: 0, insurance: 0 } } pub fn hit(&mut self) { if self.hands[self.active].blackjack() || self.hands[self.active].doubled { return; } let card = self.shoe.deal(); self.hands[self.active].cards.push(card); if self.hands[self.active].value().0 >= 21 { self.next_hand(); } } pub fn stand(&mut self) { self.next_hand(); } pub fn split(&mut self) -> bool { if self.hands.len() >= 4 || !self.hands[self.active].pair() { return false; } let bet = self.hands[self.active].bet; let card = self.hands[self.active].cards.pop().expect("pair has cards"); let mut next = Hand::new(bet); next.cards.push(card); self.hands[self.active].cards.push(self.shoe.deal()); next.cards.push(self.shoe.deal()); if next.cards[0].rank == Rank::Ace { next.doubled = true; } self.hands.insert(self.active + 1, next); true } pub fn dealer_play(&mut self, hits_soft_17: bool) { while self.dealer.value().0 < 17 || (hits_soft_17 && self.dealer.value() == (17, true)) { let card = self.shoe.deal(); self.dealer.cards.push(card); } } fn next_hand(&mut self) { if self.active + 1 < self.hands.len() { self.active += 1; } else { self.over = true; } } }
#[cfg(test)] mod tests { use super::*; use crate::cards::{Card, Rank, Suit}; fn h(ranks: &[Rank]) -> Hand { Hand { cards: ranks.iter().map(|r| Card { rank: *r, suit: Suit::Spades }).collect(), bet: 100, surrendered: false, doubled: false } } #[test] fn aces_are_soft_then_hard() { assert_eq!(h(&[Rank::Ace, Rank::Six]).value(), (17, true)); assert_eq!(h(&[Rank::Ace, Rank::King, Rank::Five]).value(), (16, false)); } #[test] fn blackjack_detected() { assert!(h(&[Rank::Ace, Rank::King]).blackjack()); } #[test] fn payouts_follow_mode() { assert_eq!(payout(&h(&[Rank::Ten, Rank::Seven]), &h(&[Rank::Ten, Rank::Six]), Mode::Double), 100); assert_eq!(payout(&h(&[Rank::Ace, Rank::King]), &h(&[Rank::Ten, Rank::Nine]), Mode::Classic), 150); } #[test] fn split_creates_hand() { let mut r = Round::new(Shoe::new(), 10); r.hands[0].cards = vec![Card { rank: Rank::Eight, suit: Suit::Spades }, Card { rank: Rank::Eight, suit: Suit::Hearts }]; assert!(r.split()); assert_eq!(r.hands.len(), 2); } #[test] fn dealer_stands_on_seventeen() { let mut r = Round::new(Shoe::new(), 10); r.dealer.cards = vec![Card { rank: Rank::Ten, suit: Suit::Spades }, Card { rank: Rank::Seven, suit: Suit::Hearts }]; r.dealer_play(false); assert_eq!(r.dealer.value().0, 17); } }
